        List<Owned> owned = new ArrayList<>();
        for (String table : order) {
            List<String> cols = columns.get(table);
            String cond = null;
            if (table.equals(ROOT)) {
                cond = "ID = ?";
            } else if (cols.contains("SHEET_ID")) {
                cond = "SHEET_ID = ?";
            } else {
                for (Map.Entry<String, String[]> r : refs.get(table).entrySet()) {
                    String parent = owns.get(r.getValue()[0]);
                    if (parent != null) {
                        cond = quote(r.getKey()) + " IN (SELECT " + quote(r.getValue()[1]) + " FROM "
                                + quote(r.getValue()[0]) + " WHERE " + parent + ")";
                        break;
                    }
                }
            }
            if (cond == null) continue;
            owns.put(table, cond);
            owned.add(new Owned(table, List.copyOf(cols), keys.get(table), cond));
        }
        return List.copyOf(owned);
    }

    private static String quote(String name) {
        return "\"" + name + "\"";
    }

    private static byte[] serialize(List<TableRows> snapshot) {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(new ArrayList<>(snapshot));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return bytes.toByteArray();
    }

    @SuppressWarnings("unchecked")
    private static List<TableRows> deserialize(byte[] data) {
        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (List<TableRows>) in.readObject();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } catch (ClassNotFoundException e) {
            throw new IllegalStateException(e);
        }
    }
}
import { HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/**
 * While the signed-in user has an as-of date set, every call to a sheet carries it: the server shows
 * the sheet as it stood at the end of that date and refuses every change. A call marked {@link LIVE}
 * reads what the store holds now, whatever the as-of date.
 */
/** Marks a read that is of the store as it is now, never as of the user's date. */
export const LIVE = new HttpContextToken<boolean>(() => false);

export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  if (asOf === null || req.context.get(LIVE) || !req.url.startsWith('/api/sheets/')) return next(req);
  return next(req.clone({ setHeaders: { 'X-As-Of': asOf } }));
};

