import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /**
     * A period as the screen shows it; once closed, with the due-total fixed then and each person's
     * due-total for it fixed then, by person id (two decimals; empty while open). Soft-closed, the
     * figures are fixed the same way while it is not closed.
     */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedDueTotal, Map<Long, String> closedPersonDues, Integer cap) {
        static PeriodView of(Period period) {
            Map<Long, String> personDues = new TreeMap<>();
            period.getClosedPersonDues().forEach((personId, due) -> personDues.put(personId, due.setScale(2).toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedDueTotal() == null ? null : period.getClosedDueTotal().setScale(2).toPlainString(),
                    personDues, period.getCap());
        }
    }

    /**
     * A name of letters, digits, '.', '_' or '-', a from and to date, both inclusive, and a cap on each
     * person's OPEN or PENDING claims in it (null: none).
     */
    public record PeriodRequest(
            @NotNull @Pattern(regexp = "[A-Za-z0-9._-]{1,100}") String name,
            @NotNull LocalDate from,
            @NotNull LocalDate to,
            @Positive Integer cap) {}

    /** The first and last dates whose months get a period each; blank takes the sheet's today. */
    public record GenerateRequest(LocalDate from, LocalDate to) {}

    /** A fiscal year by the calendar year its first day falls in (yyyy). */
    public record GenerateFiscalYearRequest(@NotNull @Pattern(regexp = "\\d{4}") String year) {}

    private final PeriodService service;
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { FigurePipe } from '../../core/figure';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first and last dates (yyyy-mm-dd) in it, both inclusive. */
  from: string;
  to: string;
  /** Once closed, no claim due inside it can change. */
  closed: boolean;
  /** Soft-closed: its figures are fixed as for a close, but claims due inside it can still change. */
  softClosed: boolean;
  /** The due-total fixed when it was closed or soft-closed, two decimals; null while open. */
  closedDueTotal: string | null;
  /** Each person's due-total for it fixed when it was closed, two decimals, by person id; empty while open. */
  closedPersonDues: Record<string, string>;
  /** The most OPEN or PENDING claims a person may have in it; null for no cap. */
  cap: number | null;
}

/** Of the sheet's periods, the one whose dates contain the date, or null. */
export function periodOn(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/**
 * The fiscal year a date (yyyy-mm-dd) falls in, named FY<yyyy> by the calendar year its first day (the
 * first of the start month, 1 to 12) falls in.
 */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

